const saveKey=new URLSearchParams(location.search).has('test-run')?'poketactics-test-match-v1':'poketactics-match-v1';
const replayKey=saveKey+'-replays-v1';
let g:Game=freshMatch();try{const saved=localStorage.getItem(saveKey);if(saved){const parsed=JSON.parse(saved);if([4,5].includes(parsed.schemaVersion)&&parsed?.lobby?.rivals?.length===7&&parsed.units&&parsed.round>=1&&parsed.round<=80&&parsed.health>0&&!parsed.lobby.placement){g=parsed;for(const p of [g,...g.lobby!.rivals])p.inventory??=['power','wise','vital'];if(parsed.resolved)advanceLobbyRound(g);}}}catch{}
let phase:'prep'|'battle'|'result'|'replay'='prep',selected:number|null=null, fighters:Fighter[]=[],hits:Hit[]=[],elapsed=0,speed=1,muted=true,last=0,animation=0,won=false;
const battleAudio=new BattleAudio();
let battleSession:BattleSession|null=null,replayPaused=false,replayReturn:'prep'|'battle'|'result'='prep';
let replaySavedSession:BattleSession|null=null;
let replayRecords:BattleRecord[]=[];try{const stored=JSON.parse(localStorage.getItem(replayKey)||'[]');if(Array.isArray(stored))replayRecords=stored.filter(validateRecord).slice(0,10);}catch{}
let lastReport:Fighter[]=[], hovered=-1,itemSelected:number|null=null;
const canvas=$('board') as HTMLCanvasElement,ctx=canvas.getContext('2d')!;
let width=0,height=0,unitScale=1;
const rotateQuery=matchMedia('(max-width:600px) and (orientation:portrait)');
const mobileQuery=matchMedia('(max-width:600px), (max-width:1000px) and (max-height:520px)');
function mobileLayout(){return mobileQuery.matches;}
function geometry(){const narrow=width<600,size=Math.min(narrow?(width-95)/14.4:width/17,height/10.8,54);const phone=mobileLayout();const touchSize=phone?Math.min((width-24)/13.4,(height-8)/9.5,54):size;return {size:touchSize,ox:(width+(narrow&&!phone?80:0))/2-touchSize*5.64,oy:height/2-touchSize*3.72+(phone?0:35)};}
function point(x:number,y:number){const {size,ox,oy}=geometry();return {x:ox+x*size*1.73,y:oy+y*size*1.73};}
function slotPoint(slot:number){const p=cell(slot);return point(p.x,p.y);}
function save(){if(phase==='replay')return;try{localStorage.setItem(saveKey,JSON.stringify({...g,schemaVersion:5,resolved:phase==='result'}));$('save-status').textContent='✓ Adventure saved';}catch{$('save-status').textContent='Saving unavailable';}}
let toastTimer:number;function toast(message:string){if(!message)return;$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=window.setTimeout(()=>$('toast').classList.remove('show'),2800);}
function tone(freq=440){if(muted)return;try{const ac=new AudioContext(),o=ac.createOscillator(),gain=ac.createGain();o.type='sine';o.frequency.value=freq;gain.gain.setValueAtTime(.045,ac.currentTime);gain.gain.exponentialRampToValueAtTime(.001,ac.currentTime+.15);o.connect(gain);gain.connect(ac.destination);o.start();o.stop(ac.currentTime+.15);o.onended=()=>ac.close();}catch{}}
function sprite(id:number,cls=''){return `<img class="sprite animated-sprite ${cls}" src="${spriteURL(id)}" alt="${species(id).name}" draggable="false">`;}
function types(id:number){return species(id).types.map(t=>`<span class="type-icon" style="--type:${colors[t]}" title="${t}">${({Grass:'♧',Water:'♦',Fire:'♨',Electric:'ϟ',Poison:'◉',Normal:'✧',Psychic:'✦',Rock:'⬟'})[t]}</span>`).join('');}
function stars(star:number){return `<span class="stars">${'★'.repeat(star)}</span>`;}
function render(){
 const shownRound=phase==='replay'&&battleSession?battleSession.record.round:g.round;const displayUnits=phase==='replay'&&battleSession?battleSession.record.initial.filter(f=>!f.team).map(f=>({uid:f.uid,species:f.species,star:f.star,slot:f.slot,board:true})):g.units;
 $('health').textContent=`${g.health}`;$('healthbar').style.width=`${g.health}%`;$('round-label').textContent=phase==='replay'&&battleSession?`REPLAY · SEED ${battleSession.record.seed} · ${battleSession.record.initial.filter(f=>!f.team).length} vs ${battleSession.record.initial.filter(f=>f.team).length}`:`STAGE ${stageLabel(shownRound)} · ${g.lobby?.roundKind==='neutral'?'WILD POKÉMON':g.lobby?.roundKind==='draft'?'POKÉMON DRAFT':'TRAINER BATTLE'}`;
 $('phase-label').textContent=phase==='replay'?'Battle replay':phase==='battle'?'The battle is on':phase==='result'?(won?'Victory! Well played.':'Regroup and try again'):g.lobby?.roundKind==='draft'?'Choose a Pokémon from the shared draft':g.lobby?.roundKind==='pvp'?`Prepare against ${trainerName(g,g.lobby.opponent)}`:'Prepare your team';
 $('phase-pill').textContent=phase==='replay'?'REPLAY':phase==='battle'?'IN COMBAT':phase==='result'?'ROUND COMPLETE':'PREPARATION';$('phase-pill').className=`phase-pill ${phase}`;
 $('round-path').innerHTML=Array.from({length:7},(_,i)=>`<span class="path-node ${i+1===Number(stageLabel(g.round).split('-')[1])?'current':''}" title="Stage round ${i+1}">${i===3?'♧':i===6?'◇':i+1}</span>${i<6?'<i></i>':''}`).join('');

 const boardCount=displayUnits.filter(u=>u.board).length;$('capacity').innerHTML=`<span>♟</span> <b>${boardCount}</b> / ${phase==='replay'&&battleSession?(battleSession.record.capacity??boardCount):g.level}<small>TEAM SIZE</small>`;
 $('gold').textContent=String(g.gold);$('interest').textContent=`+${Math.min(5,Math.floor(g.gold/10))} interest · +${streakBonus(g.streak)} streak`;
 $('level').textContent=String(g.level);$('xp-label').textContent=g.level===9?'Maximum level':`${g.xp} / ${xpToNext(g.level)} XP`;$('xpbar').style.width=`${g.level===9?100:g.xp/(xpToNext(g.level))*100}%`;
 const alive=1+g.lobby!.rivals.filter(p=>p.health>0).length-(g.health<=0?1:0);$('stage-progress').textContent=`${alive} trainers remain`;$('stagebar').style.width=`${(8-alive)/7*100}%`;
 const syn=synergies(displayUnits).sort((a,b)=>b[1]-a[1]);$('synergy-count').textContent=String(syn.filter(([,n])=>n>=2).length);
 $('synergies').innerHTML=syn.map(([t,n])=>{const ids=[...new Set(displayUnits.filter(u=>u.board&&species(u.species).types.includes(t)).map(u=>u.species))],tier=traitTier(t,n),thresholds=traits[t].tiers,next=thresholds.find(v=>v>n)??thresholds[thresholds.length-1],maxed=tier===thresholds.length;return `<div class="synergy ${tier?'active':''}" style="--type:${colors[t]}" tabindex="0" aria-label="${t}: ${n} unique Pokémon. ${traitText(t,n)}"><span class="synergy-icon">${types(speciesForType(t)).match(/<span[^>]*>[^<]*<\/span>/)?.[0]||'✧'}</span><div class="synergy-title"><strong>${t}</strong><small>${tier?'TIER '+tier:'NEEDS '+(2-n)+' MORE'}</small></div><span class="synergy-count">${n}<em> / ${maxed?'MAX':next}</em></span><div class="synergy-dots">${Array.from({length:next},(_,i)=>`<i class="${i<n?'lit':''}"></i>`).join('')}</div><div class="synergy-details"><strong>${traits[t].name}<span>${tier?'TIER '+tier:'INACTIVE'}</span></strong><p>${thresholds.map((threshold,i)=>`<b>${threshold}:</b> ${traits[t].summaries[i]}`).join('<br>')}</p>${elementGuides[t]?`<p><b>${elementGuides[t]!.identity}</b><br>${elementGuides[t]!.counter}</p><p>${elementGuides[t]!.positioning}</p>`:""}<div class="trait-contributors">${ids.map(id=>`<div>${sprite(id)}<small>${species(id).name}</small></div>`).join('')}</div><small>Only distinct deployed species count. Bonuses apply to matching Pokémon.</small></div></div>`;}).join('')||'<p class="no-synergies">Deploy Pokémon to activate type bonuses.</p>';
 $('bench').innerHTML=Array.from({length:9},(_,i)=>{const u=g.units.find(v=>!v.board&&v.slot===i);return `<button class="bench-slot ${u?'occupied':''} ${u&&selected===u.uid?'selected':''}" data-slot="${i}" data-uid="${u?.uid??''}" title="${u?`${species(u.species).name} · ${u.star} star. Click then choose a hex.`:'Empty bench slot'}" aria-label="${u?species(u.species).name:'Bench slot '+(i+1)}" ${u?'draggable="true"':''}>${u?`${stars(u.star)}${sprite(u.species)}`:`<span>${i+1}</span>`}</button>`;}).join('');
 $('shop-cards').innerHTML=g.shop.map((id,i)=>{if(!id)return `<div class="shop-card sold"><span>✓</span><small>RECRUITED</small></div>`;const s=species(id);return `<button class="shop-card tier-${s.cost}" data-buy="${i}" style="--type:${colors[s.types[0]]}" ${phase!=='prep'?'disabled':''} title="${s.name} · ${s.hp} HP · ${s.atk} attack · ${roles[id]}: ${roleDescriptions[roles[id]]} · ${s.ability}: ${skills[s.id].description} · ${skillRules(s.id)}"><div class="card-types">${types(id)}</div><span class="rarity">${'◆'.repeat(s.cost)}</span>${sprite(id)}<div class="card-bottom"><strong>${s.name}</strong><span><span class="coin">₽</span> ${s.cost}</span></div><div class="card-detail">${roles[id]} · ${remainingCopies(g,id)} copies left</div></button>`;}).join('');
 ($('lock') as HTMLButtonElement).disabled=phase==='replay';($('xp') as HTMLButtonElement).disabled=phase!=='prep'||g.level>=9;($('reroll') as HTMLButtonElement).disabled=phase!=='prep';
 $('lock').textContent=g.locked?'▣':'♧';$('lock').classList.toggle('locked',g.locked);$('lock').setAttribute('aria-label',g.locked?'Unlock shop':'Lock shop');
 $('battle').innerHTML=phase==='battle'?`<span>⚔</span> Battling <span class="battle-time">${Math.floor(elapsed)}s</span>`:phase==='result'?`Continue <span>→</span>`:g.lobby!.roundKind==='draft'?`<span>♧</span> Choose Pokémon <kbd>SPACE</kbd>`:`<span>⚔</span> Battle <kbd>SPACE</kbd>`;($('battle') as HTMLButtonElement).disabled=phase==='battle'||phase==='replay';
 const opponent=phase==='replay'&&battleSession?battleSession.record.initial.filter(f=>f.team).map(f=>({uid:f.uid,species:f.species,star:f.star,slot:f.slot,board:true})):opponentUnits(g);$('enemy-count').textContent=`${opponent.length} Pokémon · ${g.lobby?.roundKind==='neutral'?'Neutral round':'Trainer lineup'}`;$('opponent-name').textContent=g.lobby?.roundKind==='neutral'?'Wild Pokémon':g.lobby?.roundKind==='draft'?'Shared Pokémon draft':trainerName(g,g.lobby!.opponent);$('reward').textContent=String(5+streakBonus(g.streak));$('enemy-preview').innerHTML=opponent.map(u=>`<div title="${species(u.species).name}">${sprite(u.species)}${stars(u.star)}</div>`).join('');
 $('board-caption').textContent=phase==='replay'&&battleSession?`Replay · seed ${battleSession.record.seed} · ${battleSession.record.ruleset}`:phase==='battle'?'Your Pokémon battle automatically':phase==='result'?'Review your team and continue your adventure':selected?'Click a highlighted hex to place your Pokémon':'Drag Pokémon onto your side of the battlefield';
 ($('sell') as HTMLButtonElement).disabled=selected===null||phase!=='prep';renderEconomyGuide();renderUnits();renderEquipment();drawBoard();renderStandings();renderMobileControls();refreshBattleMeter();if(phase!=='replay')save();
}
function speciesForType(t:string){return ({Grass:1,Water:7,Fire:4,Electric:25,Poison:92,Normal:52,Psychic:63,Rock:74} as Record<string,number>)[t];}
function renderUnits(){const list=phase==='prep'?[...g.units.filter(u=>u.board).map(u=>({...u,team:0})),...opponentUnits(g).map(u=>({...u,team:1}))]:[];
 $('units-layer').innerHTML=list.map(u=>{const p=slotPoint(u.slot),s=species(u.species);return `<button class="board-unit ${u.team?'enemy':'ally'} ${selected===u.uid?'selected':''}" style="left:${p.x}px;top:${p.y}px;--unit-scale:${unitScale}" data-uid="${u.uid}" ${!u.team?'draggable="true"':''} title="${s.name} · ${roles[s.id]}: ${roleDescriptions[roles[s.id]]} · ${s.ability}: ${skills[s.id].description} · ${skillRules(s.id)} · ${Math.round(makeFighter(u,u.team).maxHp)} HP" aria-label="${u.team?'Opponent ':'Your '}${s.name}">${stars(u.star)}<div class="unit-health"><i></i></div>${sprite(u.species)}${equipmentBadges(u.items)}<span class="unit-name">${s.name}</span></button>`;}).join('');
 if(phase!=='prep')$('units-layer').innerHTML=fighters.map(f=>`<div id="fighter-${f.uid}" class="board-unit ${f.team?'enemy':'ally'} fighter" data-uid="${f.uid}" tabindex="0" role="button" aria-label="Inspect ${species(f.species).name}" style="--unit-scale:${unitScale}">${stars(f.star)}<div class="unit-health"><i></i></div><div class="unit-mana"><i></i></div><div class="unit-shield"><i></i></div>${sprite(f.species)}${equipmentBadges(f.items)}<span class="unit-name">${species(f.species).name}</span></div>`).join('');
 updateFighters();
}
function updateFighters(){for(const f of fighters){
 const el=$(`fighter-${f.uid}`);if(!el)continue;
 const p=point(f.x,f.y),attack=[...hits].reverse().find(h=>h.attacker===f.uid&&h.primary&&h.life/(h.duration??1)>.64);
 const visibleHp=f.hp;
 el.classList.toggle('inspected',inspectedUid===f.uid&&!inspector.classList.contains('hidden'));const watchedHit=[...hits].reverse().find(h=>h.attacker===inspectedUid&&h.primary);el.classList.toggle('inspect-targeted',!!watchedHit&&watchedHit.target===f.uid&&f.hp>0&&f.uid!==inspectedUid&&!inspector.classList.contains('hidden'));el.dataset.slot=String(f.slot);el.dataset.reservedSlot=f.moveTo===null?'':String(f.moveTo);
 el.style.left=`${p.x}px`;el.style.top=`${p.y}px`;el.style.opacity=visibleHp<=0?'0':'1';
 const impact=hits.some(h=>h.target===f.uid&&h.life/(h.duration??1)<=.66&&h.life/(h.duration??1)>.5);
 el.style.filter=impact?(fighters.length>=12&&!mobileLayout()?'brightness(1.18)':'brightness(1.65)'):f.statuses.some(s=>s.kind==='poison')?'drop-shadow(0 0 4px #bb86ef)':f.shield>0?'drop-shadow(0 0 5px #9de0ff)':'';el.dataset.status=f.statuses.map(s=>s.kind).join(' ');el.style.zIndex=String(Math.floor(f.y*10)+20);
 let lx=0,ly=0;
 if(attack){const to=point(attack.toX,attack.toY),dx=to.x-p.x,dy=to.y-p.y,d=Math.hypot(dx,dy)||1,age=1-attack.life/(attack.duration??1);
 const motion=age<.12?-Math.sin(age/.12*Math.PI)*2:Math.sin((age-.12)/.24*Math.PI)*5;
 lx=dx/d*motion;ly=dy/d*motion;
 el.dataset.attacking=String(attack.target);el.dataset.attackLabel=`${species(f.species).name} → ${species(fighters.find(t=>t.uid===attack.target)?.species??f.species).name}${attack.ability?' · '+attack.ability:''}`;
 }else el.dataset.attacking='';
 el.style.setProperty('--facing',String(spriteFacing(f,fighters,hits)));el.style.setProperty('--lunge-x',`${lx}px`);el.style.setProperty('--lunge-y',`${ly}px`);
 (el.querySelector('.unit-health i') as HTMLElement).style.width=`${visibleHp/f.maxHp*100}%`;
 (el.querySelector('.unit-shield') as HTMLElement).style.display=f.shield>0?'block':'none';(el.querySelector('.unit-shield i') as HTMLElement).style.width=`${Math.min(100,f.shield/f.maxHp*100)}%`;
 (el.querySelector('.unit-mana i') as HTMLElement).style.width=`${Math.min(100,f.mana/skills[f.species].mana*100)}%`;
 let state=el.querySelector<HTMLElement>('.unit-state');if(!state){state=document.createElement('span');state.className='unit-state';el.appendChild(state);}const signs={burn:'♨',poison:'☣',stun:'✦',root:'♧',slow:'❄'};state.textContent=f.statuses.map(s=>signs[s.kind]).join('')+(f.shield>0?' ◈':'');state.title=f.statuses.map(s=>`${s.kind} ${s.time.toFixed(1)}s`).join(', ')+(f.shield>0?` · ${Math.round(f.shield)} shield`:'');
}}
function drawBoard(){ctx.clearRect(0,0,width,height);const {size}=geometry();const top=slotPoint(0),bottom=slotPoint(41);drawIsland(ctx,width,height,{left:top.x-size,top:top.y-size,right:bottom.x+size,bottom:bottom.y+size});for(let slot=0;slot<42;slot++){const p=slotPoint(slot),row=Math.floor(slot/7),ally=row>=3;const occupied=phase==='prep'?g.units.some(u=>u.board&&u.slot===slot):fighters.some(f=>!f.team&&f.hp>0&&(f.slot===slot||f.moveTo===slot));const enemyOccupied=phase==='prep'?opponentUnits(g).some(u=>u.slot===slot):fighters.some(f=>f.team&&f.hp>0&&(f.slot===slot||f.moveTo===slot));ctx.beginPath();for(let i=0;i<6;i++){const angle=(i*60-30)*Math.PI/180,x=p.x+Math.cos(angle)*(size-1.3),y=p.y+Math.sin(angle)*(size-1.3);i?ctx.lineTo(x,y):ctx.moveTo(x,y);}ctx.closePath();const stone=ctx.createLinearGradient(p.x,p.y-size,p.x,p.y+size);stone.addColorStop(0,ally?(slot%2?'#a4b46a':'#adbc74'):(slot%2?'#c29c73':'#cda67d'));stone.addColorStop(1,ally?(slot%2?'#899d58':'#97aa60'):(slot%2?'#a98061':'#b78c69'));ctx.fillStyle=slot===hovered&&ally&&phase==='prep'?'#708b68':stone;ctx.fill();ctx.strokeStyle=occupied&&ally?'#a4df8c':selected&&ally?'#c5dda670':enemyOccupied?'#e3a68b':'#605d3a';ctx.lineWidth=occupied&&ally||enemyOccupied?2.5:1.2;ctx.stroke();if(occupied&&ally){ctx.shadowColor='#a4ee85';ctx.shadowBlur=9;ctx.stroke();ctx.shadowBlur=0;}ctx.strokeStyle='#ffffff18';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(p.x-size*.6,p.y-size*.32);ctx.lineTo(p.x-size*.62,p.y+size*.35);ctx.stroke();}
 // The illuminated line separates the two deployment zones.
 const a=slotPoint(21),b=slotPoint(27);ctx.beginPath();ctx.moveTo(a.x-size*.8,a.y-size*.78);ctx.lineTo(b.x+size*.8,b.y-size*.78);ctx.strokeStyle='#b4926840';ctx.setLineDash([4,8]);ctx.stroke();ctx.setLineDash([]);
}
function resize(){const rect=$('battle-surface').getBoundingClientRect();width=rect.width;height=rect.height;canvas.width=width*devicePixelRatio;canvas.height=height*devicePixelRatio;canvas.style.width=`${width}px`;canvas.style.height=`${height}px`;ctx.setTransform(devicePixelRatio,0,0,devicePixelRatio,0,0);unitScale=Math.min(1.25,geometry().size/39);drawBoard();renderUnits();positionEconomyGuide();renderMobileControls();}
