function getSlot(e:MouseEvent|DragEvent){const r=canvas.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top;let nearest=-1,dist=Infinity;for(let i=0;i<42;i++){const p=slotPoint(i),d=Math.hypot(p.x-x,p.y-y);if(d<dist){dist=d;nearest=i;}}return dist<geometry().size?nearest:-1;}
function move(uid:number,slot:number,board:boolean){if(phase!=='prep')return;const err=place(g,uid,slot,board);if(err)toast(err);else{selected=null;tone(520);render();}}
let pointerDrag:{uid:number;startX:number;startY:number;moved:boolean;source:HTMLElement;ghost:HTMLElement|null;pointerType:string;pointerId:number;surface:'board'|'bench';panAxis:'x'|'y';previousSelection:number|null}|null=null;
