app.addEventListener('pointerdown',e=>{const source=(e.target as HTMLElement).closest<HTMLElement>('[data-uid]');const u=g.units.find(v=>v.uid===Number(source?.dataset.uid));if(!source||!u||phase!=='prep'||e.button!==0)return;if(itemSelected!==null)return;if(e.pointerType!=='touch')e.preventDefault();pointerDrag={uid:u.uid,startX:e.clientX,startY:e.clientY,moved:false,source,ghost:null,pointerType:e.pointerType,pointerId:e.pointerId,surface:source.closest('#bench')?'bench':'board',panAxis:getComputedStyle($('bench')).getPropertyValue('--bench-pan-axis').trim()==='y'?'y':'x',previousSelection:selected};});
app.addEventListener('pointermove',e=>{const d=pointerDrag;if(!d)return;if(!d.moved){const intent=gestureIntent(d.pointerType,d.surface,e.clientX-d.startX,e.clientY-d.startY,d.panAxis);if(intent==='scroll'){pointerDrag=null;return;}if(intent==='pending')return;d.source.setPointerCapture(d.pointerId);d.moved=true;selected=d.uid;d.ghost=document.createElement('div');d.ghost.className='drag-ghost';d.ghost.innerHTML=sprite(g.units.find(u=>u.uid===d.uid)!.species);document.body.appendChild(d.ghost);d.source.style.opacity='.35';($('sell') as HTMLButtonElement).disabled=false;drawBoard();}if(!d.moved)return;e.preventDefault();if(d.ghost){d.ghost.style.left=`${e.clientX}px`;d.ghost.style.top=`${e.clientY}px`;}showShopSale(document.elementFromPoint(e.clientX,e.clientY)?.closest('.shop')?d.uid:null);hovered=getSlot(e);drawBoard();});
app.addEventListener('pointerup',e=>{const d=pointerDrag;if(!d)return;pointerDrag=null;d.source.style.opacity='';d.ghost?.remove();if(!d.moved)return;hovered=-1;const target=document.elementFromPoint(e.clientX,e.clientY);showShopSale(null);if(target?.closest('.shop')||target?.closest('#sell'))performSale(d.uid);else if(target?.closest('#bench')){const slot=target.closest<HTMLElement>('[data-slot]');if(slot)move(d.uid,Number(slot.dataset.slot),false);}else if(target?.closest('#arena')){const slot=getSlot(e);if(slot>=0)move(d.uid,slot,true);}suppressDragClick();drawBoard();});
app.addEventListener('pointercancel',()=>{const d=pointerDrag;d?.ghost?.remove();if(d)d.source.style.opacity='';pointerDrag=null;showShopSale(null);hovered=-1;if(d?.moved){selected=d.previousSelection;render();}else drawBoard();});
app.addEventListener('dragstart',e=>{const target=(e.target as HTMLElement).closest<HTMLElement>('[data-uid]');if(!target||phase!=='prep'||!g.units.some(u=>u.uid===Number(target.dataset.uid))){e.preventDefault();return;}selected=Number(target.dataset.uid);($('sell') as HTMLButtonElement).disabled=false;e.dataTransfer?.setData('text/plain',String(selected));if(e.dataTransfer)e.dataTransfer.effectAllowed='move';drawBoard();});
