$('arena').addEventListener('click',e=>{if(phase!=='prep'||(e.target as Element).closest('.arena-traits,.arena-trainers,#arena-flyout,#economy-guide,#sell'))return;const unit=(e.target as HTMLElement).closest<HTMLElement>('[data-uid]');if(unit&&g.units.some(u=>u.uid===Number(unit.dataset.uid))){const uid=Number(unit.dataset.uid);if(itemSelected!==null){useItem(uid);return;}if(selected!==null&&selected!==uid){const target=g.units.find(u=>u.uid===uid)!;move(selected,target.slot,true);}else{selected=selected===uid?null:uid;render();}return;}const slot=getSlot(e);if(selected!==null&&slot>=0)move(selected,slot,true);});
