$('shop-cards').addEventListener('click',e=>{const card=(e.target as HTMLElement).closest<HTMLElement>('[data-buy]');if(!card||phase!=='prep')return;const oldStars=g.units.reduce((n,u)=>n+u.star-1,0);const err=buy(g,Number(card.dataset.buy));if(err)toast(err);else{if(mobileLayout()){selected=null;itemSelected=null;}tone(660);if(g.units.reduce((n,u)=>n+u.star-1,0)>oldStars)toast('★ Your Pokémon upgraded!');render();}});
