function startBattle(){if(phase==='battle'||phase==='replay')return;if(phase==='result'){nextRound();return;}if(g.lobby?.roundKind==='draft'){openDraft();return;}if(!g.units.some(u=>u.board))return toast('Place at least one Pokémon on the battlefield.');cancelItemDrag();equipment.classList.remove('mobile-open');bagToggle.setAttribute('aria-expanded','false');phase='battle';itemSelected=null;selected=null;$('arena-flyout').classList.add('hidden');const seed=crypto.getRandomValues(new Uint32Array(1))[0];battleSession=new BattleSession(makeRecord(prepare(g),seed,g.round,g.level));fighters=battleSession.fighters;hits=battleSession.hits;elapsed=0;$('result').classList.add('hidden');render();tone(220);}
