function inspectPokemon(uid:number){if(!mobileLayout()){inspectedUid=uid;inspectedItem=null;inspectionPinned=true;refreshInspection();return;}const f=fighters.find(v=>v.uid===uid),u=g.units.find(v=>v.uid===uid)??opponentUnits(g).find(v=>v.uid===uid);if(!f&&!u)return;const id=(f??u)!.species,star=(f??u)!.star,s=species(id),stats=f??makeFighter(u!,uid<0?1:0);showArenaPanel(`<small class="eyebrow">POKÉMON DETAILS · ${roles[id]}</small><h2>${s.name} ${'★'.repeat(star)}</h2><p>${s.types.join(' / ')} · ${Math.round(stats.maxHp)} HP · ${Math.round(stats.atk)} attack · ${s.range}-hex range</p><h3>${skills[id].name}</h3><p>${skills[id].description}</p><p>${skillRules(id)}</p><p>${(stats.items??[]).map(id=>`${item(id)!.icon} ${item(id)!.name}: ${itemDescription(id)}`).join("<br>")||"No held items"}</p><p>${manaRules(roles[id])}</p><p>${roleDescriptions[roles[id]]}</p>`);}

