function itemTarget(uid:number){const u=g.units.find(u=>u.uid===uid),id=itemSelected===null?undefined:g.inventory?.[itemSelected];if(!u||!id)return;const crafted=u.items?.map(old=>recipe(old,id)).find(Boolean);return {u,id,crafted,allowed:!!crafted||(u.items?.length??0)<3};}
